//! The UI twin (docs/spec/themes.md, phase 1): the same typed API `slint-build` gives Lag, generated by
//! `build_twin.rs`, but backed by the interpreter so the UI can come from files at run time (themes).
//! Not wired into the app yet: phase 1 switches the call sites over step by step.
#![allow(dead_code, unused_imports, clippy::all)]
pub mod rt;
pub use rt::{TwinComponent, Weak};
include!(concat!(env!("OUT_DIR"), "/ui_twin.rs"));

#[cfg(test)]
mod tests {
    use super::*;
    use slint::platform::software_renderer::{MinimalSoftwareWindow, RepaintBufferType};
    use std::rc::Rc;

    struct Headless(Rc<MinimalSoftwareWindow>);
    impl slint::platform::Platform for Headless {
        fn create_window_adapter(&self) -> Result<Rc<dyn slint::platform::WindowAdapter>, slint::PlatformError> {
            Ok(self.0.clone())
        }
    }

    /// The generated API drives Lag's whole interpreted UI exactly like the compiled one: typed properties,
    /// structs in models, enums, callbacks both ways.
    #[test]
    fn the_twin_drives_the_interpreted_ui() {
        let _ = slint::platform::set_platform(Box::new(Headless(MinimalSoftwareWindow::new(RepaintBufferType::NewBuffer))));
        let ui_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("ui");
        rt::load(&ui_dir.join("app.slint"), &ui_dir).expect("Lag's UI compiles at run time");
        let ui = AppWindow::new().expect("window");

        let main = ui.global::<MainVM>();
        main.set_is_recording(true);
        assert!(main.get_is_recording());
        main.set_current_page(Page::Library);
        assert_eq!(main.get_current_page(), Page::Library);

        // a callback from the UI reaches Rust, with its argument typed
        let seen = Rc::new(std::cell::Cell::new(None));
        let s = seen.clone();
        main.on_navigate(move |p| s.set(Some(p)));
        main.invoke_navigate(Page::Player);
        assert_eq!(seen.get(), Some(Page::Player));

        // Rust implements a pure callback the UI calls (translations)
        ui.global::<Tr>().on_t(|key, _| format!("<{key}>").into());
        assert_eq!(ui.global::<Tr>().invoke_t("X".into(), 0), "<X>");

        // structs inside a model, both ways
        let rows = slint::VecModel::from(vec![SettingsRowData { id: "a".into(), kind: 17, selected: 3, ..Default::default() }]);
        let group = SettingsGroup { title: "T".into(), rows: slint::ModelRc::new(rows) };
        let s = ui.global::<SettingsVM>();
        s.set_groups(slint::ModelRc::new(slint::VecModel::from(vec![group])));
        use slint::Model;
        let back = s.get_groups().row_data(0).unwrap();
        assert_eq!(back.title, "T");
        assert_eq!(back.rows.row_data(0).unwrap().selected, 3);
    }
}
